// =============================================
// Prep Alert Insert
// Flattens all alert fields for the Postgres INSERT.
// alert_severity is already mapped in Build Alert Content.
// =============================================

const items = $input.all();
const result = [];

for (const item of items) {
  const d = item.json;
  const esc = (val) => val == null ? '' : String(val).replace(/\0/g, '').replace(/'/g, "''");

  // Validate alert_severity against DB constraint
  const validSeverities = ['info', 'warning', 'high', 'critical'];
  const severity = validSeverities.includes(d.alert_severity) ? d.alert_severity : 'info';

  result.push({
    json: {
      p_detection_id: d.detection_id,
      p_alert_title: esc('Amenaza ' + severity + ' detectada'),
      p_alert_message: esc(d.alert_message || ''),
      p_alert_severity: severity,

      // Carry forward for Log Execution
      _original: d
    }
  });
}

return result;

// =============================================
// Summarize Skipped Items
// Counts items that did NOT trigger an alert
// (low/medium criticality) and summarizes by level.
// =============================================

const items = $input.all();
const counts = { low: 0, medium: 0 };

for (const item of items) {
  const level = item.json.criticality_level || 'low';
  counts[level] = (counts[level] || 0) + 1;
}

const summary = Object.entries(counts)
  .filter(([_, c]) => c > 0)
  .map(([level, count]) => count + ' ' + level)
  .join(', ');

console.log('Items below alert threshold: ' + (summary || 'none') + ' (total: ' + items.length + ')');

return [{ json: { skipped_total: items.length, skipped_by_level: counts, summary: summary || 'none' } }];

// =============================================
// Prep Log Execution
// Aggregates pipeline counters from upstream nodes.
// =============================================

let mentionsCollected = 0;
let mentionsProcessed = 0;
let sentimentInserted = 0;
let detectionsGenerated = 0;
let alertsGenerated = 0;

try { mentionsCollected = $('Deduplicate').all().length; } catch(e) {}
try { mentionsProcessed = $('Insert Social Mention').all().length; } catch(e) {}
try { sentimentInserted = $('Insert Sentiment Analysis').all().length; } catch(e) {}
try { detectionsGenerated = $('Insert Threat Detection').all().length; } catch(e) {}
try { alertsGenerated = $('Log Alert in DB').all().length; } catch(e) {}

// Count errors: items that entered an INSERT but failed (had error or missing ID)
let mentionErrors = 0;
let sentimentErrors = 0;
let threatErrors = 0;
try {
  const mentionResults = $('Insert Social Mention').all();
  mentionErrors = mentionResults.filter(i => i.json.error || !i.json.mention_id).length;
} catch(e) {}
try {
  const sentimentResults = $('Insert Sentiment Analysis').all();
  sentimentErrors = sentimentResults.filter(i => i.json.error || !i.json.sentiment_id).length;
} catch(e) {}
try {
  const threatResults = $('Insert Threat Detection').all();
  threatErrors = threatResults.filter(i => i.json.error || !i.json.detection_id).length;
} catch(e) {}

const totalErrors = mentionErrors + sentimentErrors + threatErrors;

// Get skipped items summary from Summarize Skipped Items node
let skippedSummary = '';
try {
  const skipped = $('Summarize Skipped Items').all();
  if (skipped.length > 0 && skipped[0].json.summary) {
    skippedSummary = skipped[0].json.summary;
  }
} catch(e) {}

const status = totalErrors > 0 ? (mentionsProcessed === 0 ? 'error' : 'partial_success') : 'success';

if (totalErrors > 0) {
  console.warn('Execution errors — mention_insert: ' + mentionErrors + ', sentiment_insert: ' + sentimentErrors + ', threat_insert: ' + threatErrors);
}
if (skippedSummary) {
  console.log('Skipped items: ' + skippedSummary);
}

return [{
  json: {
    p_workflow_name: 'OSINT Monitor Multi-Platform',
    p_execution_id: $execution.id,
    p_status: status,
    p_mentions_collected: mentionsCollected,
    p_mentions_processed: mentionsProcessed - mentionErrors,
    p_detections_generated: detectionsGenerated - threatErrors,
    p_alerts_generated: alertsGenerated
  }
}];
